import 'package:flutter/material.dart';
import 'dart:convert';
import 'dart:typed_data';

class Base64ImageExample extends StatelessWidget {
  // Your Base64 string (without data:image/jpeg;base64, part)
  final String base64String =
      '';

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Base64 Image Example')),
      body: Center(
        child: base64String.isNotEmpty
            ? Image.memory(base64Decode(base64String))
            : Text('No image found'),
      ),
    );
  }
}

void main() {
  runApp(MaterialApp(
    home: Base64ImageExample(),
  ));
}
